'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
function setup(){const c={window:{}};vm.createContext(c);for(const f of ['white-orchard.js','map-data.js','progression-data.js','diagrams-data.js','exploration-data.js','progression-engine.js'])vm.runInContext(fs.readFileSync(f,'utf8'),c);const w=c.window;return {w,engine:w.createPhoenixProgress(w.PHOENIX_PROGRESS_DATA,w.PHOENIX_ROUTE.tasks,w.PHOENIX_ROUTE.hubs)};}
test('every regional exploration marker has a deck entry and sourced practical guidance',()=>{const {w}=setup(),{categories,details}=w.PHOENIX_EXPLORATION,{tasks}=w.PHOENIX_ROUTE,ids=categories.flatMap(c=>c.ids);assert.equal(new Set(ids).size,ids.length);for(const p of w.PHOENIX_MAP.markers.filter(p=>['pop','camp','nest','guarded','hidden','cache','abandoned','poi','signpost','buff'].includes(p.type))){if(p.id==='yellowed-diary')continue;assert.ok(ids.includes(p.task),p.id+' missing');}for(const id of ids){const d=details[id];assert.ok(tasks[id]);for(const key of ['threat','approach','fixed','variable','done'])assert.ok(d[key],id+' '+key);assert.ok(d.steps.length>=2);assert.ok(d.sources.length);for(const link of d.links)assert.ok(tasks[link],id+' -> '+link);assert.ok(w.PHOENIX_ROUTE.hubs.find(h=>h.id===tasks[id].home).items.includes(id)||id==='cow-pasture-warning');}});
test('clearing either quest-linked camp never completes a quest or acquires a diagram',()=>{const {w,engine}=setup();for(const [camp,quest,diagram] of [['camp-viper-ruins','q-viper','diagram-viper-steel'],['camp-dirty-funds','q-dirty',null]]){const fresh=engine.plan(engine.init(),{}, {kind:'activity',id:camp,value:true});assert.equal(fresh.completed[camp],true);assert.notEqual(fresh.completed[quest],true);if(diagram)assert.notEqual(fresh.completed[diagram],true);assert.equal(Object.keys(fresh.progress.objectives).length,0);assert.ok(w.PHOENIX_MAP.markers.some(p=>p.task===camp));}});
test('new camp records do not inherit old whole-quest marks on reload',()=>{const {engine}=setup(),saved=JSON.parse(JSON.stringify({'q-viper':true,'q-dirty':true}));const plan=engine.plan(engine.init({},saved),saved,{kind:'activity',id:'camp-viper-ruins',value:false});assert.equal(plan.completed['q-viper'],true);assert.notEqual(plan.completed['camp-dirty-funds'],true);});
test('each activity type has a stable authored route and precise map positions',()=>{const {w}=setup();assert.equal(w.PHOENIX_EXPLORATION.categories.length,10);for(const c of w.PHOENIX_EXPLORATION.categories)for(const id of c.ids){const pin=w.PHOENIX_MAP.markers.find(p=>p.task===id);assert.ok(pin,id);assert.ok(pin.point.every(Number.isFinite));}});
test('all power stones have independent first-draw definitions and no guessed duration',()=>{const {w}=setup();const ids=w.PHOENIX_EXPLORATION.categories.find(c=>c.id==='power').ids;assert.equal(ids.length,6);for(const id of ids){assert.match(w.PHOENIX_EXPLORATION.details[id].fixed,/One ability point/);assert.doesNotMatch(w.PHOENIX_EXPLORATION.details[id].fixed,/minute/);}});
